// Pictogrammes des pastilles de la carte : silhouettes pleines, lisibles à petite taille.
// Chaque glyphe se dessine dans un viewBox -14..14 (centré en 0,0), ~26 px de large une fois posé dans la pastille.
// Même API que react-icons (size, color) : ils remplacent directement les Icon de milBadges.js.
// À placer dans src/utils/.
import React from "react";

const make = (draw) => function Glyph({ size = 26, color = "currentColor", ...rest }) {
    return (
        <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="-14 -14 28 28"
             fill={color} stroke="none" {...rest}>
            {draw(color)}
        </svg>
    );
};

// Disque percé (hélice) : cercle R avec un trou r, rempli en evenodd.
const ring = (cx, cy, R, r) =>
    `M${cx - R} ${cy}a${R} ${R} 0 1 0 ${2 * R} 0a${R} ${R} 0 1 0 ${-2 * R} 0ZM${cx - r} ${cy}a${r} ${r} 0 1 0 ${2 * r} 0a${r} ${r} 0 1 0 ${-2 * r} 0Z`;

// Étoile d'explosion irrégulière : 8 pointes alternées longues / courtes.
const burst = (() => {
    const pts = [];
    for (let i = 0; i < 16; i++) {
        const a = (i * Math.PI) / 8 - Math.PI / 2;
        const r = i % 2 ? 6 : i % 4 === 0 ? 13 : 10.5;
        pts.push(`${(r * Math.cos(a)).toFixed(2)} ${(r * Math.sin(a)).toFixed(2)}`);
    }
    return `M${pts.join("L")}Z`;
})();

// Drone : quadricoptère vu de dessus (4 hélices, 4 bras, corps).
export const DroneGlyph = make((c) => (
    <>
        <path d="M-6.6-6.6L6.6 6.6M-6.6 6.6L6.6-6.6" stroke={c} strokeWidth="3" strokeLinecap="round" fill="none" />
        <path fillRule="evenodd" d={[[-6.6, -6.6], [6.6, -6.6], [-6.6, 6.6], [6.6, 6.6]].map(([x, y]) => ring(x, y, 3.7, 1.3)).join("")} />
        <rect x="-4.2" y="-4.2" width="8.4" height="8.4" rx="2.4" />
    </>
));

